using System;using System.IO;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;
public partial class Game {
 string businessFeedback="";
 FlowLayoutPanel BusinessPage(string title,bool kitchen){ClearPage();page="tavern-business";var surface=new CardRewardSurface{Dock=DockStyle.Fill,Art=CachedImage(Path.Combine(root,"chapters","art","tavern",kitchen?"chapter-one-kitchen.png":"chapter-one-night.png")),CompositeChildren=true};content.Controls.Add(surface);var panel=new BattleGlassPanel{Dock=DockStyle.Right,Width=Math.Min(740,Math.Max(520,content.Width*3/5)),Padding=new Padding(16)};surface.Controls.Add(panel);var body=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,BackColor=Color.Transparent,Padding=new Padding(12)};panel.Controls.Add(body);body.Controls.Add(Lab(title,20,Gold));var t=TavernBusiness.State(save);body.Controls.Add(Lab("第 "+t.day+" 个经营日 · 基础金币 "+t.baseCoins+" · 训练奖励 "+t.bonusCoins+" / 50\n每日计划：答对10个不同题目或单词；重复练习不限次数，不发经验。",11,TextColor));body.Controls.Add(PartyButton("返回驿站（保留本日进度）",ShowTavernHub,420,40));return body;}
 void BusinessText(FlowLayoutPanel body,string text){var l=Lab(text,12,TextColor);l.MaximumSize=new Size(body.Parent.Width-65,0);body.Controls.Add(l);}
 void ShowTavernBusiness(){if(!TavernBusiness.Unlocked(save)){GameMessage.Show(this,"完成第一章全部六节主线剧情后，女神将开放酒馆咒语训练。","酒馆经营尚未开放");return;}var t=TavernBusiness.State(save);if(!t.introduced){GameMessage.Show(this,"女神：驿站的灯已经亮了。从今晚起，你可以通过「咒语学习」练习听力，或通过「咒语识别」练习单词。\n正常经营每天获得100金币，完成训练计划最多额外获得50金币。若想休息，快速跳过本次经营可获得50金币。\n这些金币是我给予你的学习奖励，无需经验，也不是客人的小费。","女神 · 咒语训练开放");t.introduced=true;Persist();}var body=BusinessPage("酒馆经营 · 女神的咒语训练",false);if(t.settled){BusinessText(body,"本日已结算："+(t.baseCoins+t.bonusCoins)+"金币。可继续免费练习，或休息到下一个经营日。");body.Controls.Add(PartyButton("继续咒语识别练习",()=>ShowTavernWords(t.level),420,44));body.Controls.Add(PartyButton("继续咒语学习练习",()=>ShowTavernListeningList(t.level),420,44));body.Controls.Add(PartyButton("休息到次日",()=>{if(TavernBusiness.NextDay(save)){businessFeedback="";Persist();ShowTavernBusiness();}},420,44));return;}if(t.mode!=null){BusinessText(body,"今晚已选择"+(t.mode=="words"?"咒语识别":"咒语学习")+"。退出重进不会重复获得基础金币。");body.Controls.Add(PartyButton("继续训练",()=>{if(t.mode=="words")ShowTavernWords(t.level);else ShowTavernListeningList(t.level);},420,44));body.Controls.Add(PartyButton("结束本日经营",FinishTavernBusiness,420,44));return;}BusinessText(body,"今晚请选择一种训练。主角团负责备料、上菜和收拾，你专心完成女神的咒语练习。普通经营100金币，额外训练奖励最多50金币。");foreach(int n in new[]{4,6}){int level=n;body.Controls.Add(PartyButton("四级 / 六级".Replace("四级 / 六级",level==4?"四级":"六级")+" · 咒语学习（听力）",()=>{t.level=level;Persist();ShowTavernListeningList(level);},420,44));body.Controls.Add(PartyButton((level==4?"四级":"六级")+" · 咒语识别（单词）",()=>{t.level=level;TavernBusiness.Begin(save,"words");Persist();ShowTavernWords(level);},420,44));}body.Controls.Add(PartyButton("快速跳过酒馆经营 · 获得50金币",()=>{if(GameMessage.Show(this,"跳过本次经营只获得50金币，今天不能再领取100金币基础收益或训练奖励。仍可免费练习。是否跳过？","快速跳过经营",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;if(TavernBusiness.Skip(save)){EndTavernBusinessDay();}},420,44));}
 void FinishTavernBusiness(){var t=TavernBusiness.State(save);if(t.settled){ShowTavernBusiness();return;}if(GameMessage.Show(this,"结束后本日训练奖励将封存，可继续免费练习。当前共获得"+(t.baseCoins+t.bonusCoins)+"金币。确定结束？","经营结算",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;if(TavernBusiness.Settle(save))EndTavernBusinessDay();}
 void ShowTavernWords(int level){var t=TavernBusiness.State(save);if(!t.settled&&t.mode==null){TavernBusiness.Begin(save,"words");}if(!t.settled&&t.mode!="words"){ShowTavernBusiness();return;}var bank=Engine.Json.Deserialize<List<RogueEntry>>(File.ReadAllText(Path.Combine(root,"assets",level==4?"cet4-words.json":"cet6-words.json"))).Where(w=>w.word!=null&&w.word.Length>=4&&w.word.All(c=>c>='a'&&c<='z')).ToList();var group=Enumerable.Range(0,3).Select(i=>bank[(t.wordCursor+i)%bank.Count]).ToArray();var body=BusinessPage("厨房 · 咒语识别 · "+(level==4?"四级":"六级"),true);BusinessText(body,"根据释义拼写三个单词，完成后出菜。首次拼写错误会降低本组料理品质；可无限订正。金币来自女神的学习奖励。");if(businessFeedback.Length>0)BusinessText(body,businessFeedback);var inputs=new TextBox[3];var results=new Label[3];var correct=new bool[3];int mistakes=0;for(int i=0;i<3;i++){int at=i;BusinessText(body,(i+1)+". "+group[i].meaning);var input=new TextBox{Width=400,Font=GameTheme.Body(14),BackColor=PanelColor,ForeColor=TextColor};inputs[i]=input;body.Controls.Add(input);var result=Lab("",10,Muted);results[i]=result;body.Controls.Add(result);}bool completed=false;var wrong=new bool[3];body.Controls.Add(PartyButton("提交拼写 / 订正出菜",()=>{if(completed)return;int gain=0;for(int i=0;i<3;i++){if(correct[i])continue;if(String.Equals(inputs[i].Text.Trim(),group[i].word,StringComparison.OrdinalIgnoreCase)){correct[i]=true;inputs[i].ReadOnly=true;gain+=TavernBusiness.Reward(save,"word:"+group[i].word,true);results[i].Text="正确 · "+group[i].word;}else{if(!wrong[i]){mistakes++;wrong[i]=true;}results[i].Text="请订正："+group[i].word;}}Persist();if(correct.All(x=>x)){completed=true;t.groups++;t.wordCursor+=3;businessFeedback="出菜完成 · 品质："+(mistakes==0?"完美":mistakes==1?"良好":"普通")+" · 本次提交获得"+gain+"金币 · 今日额外奖励"+t.bonusCoins+" / 50";Persist();BusinessText(body,businessFeedback);body.Controls.Add(PartyButton("再练一组",()=>ShowTavernWords(level),420,44));}else BusinessText(body,"本次获得"+gain+"金币；订正剩余单词后即可出菜。");},420,44));body.Controls.Add(PartyButton("返回经营 / 结算",ShowTavernBusiness,420,40));}
 List<TavernListeningGroup> TavernListeningBank(int level){string file=Path.Combine(root,"assets","tavern","listening","groups.json");return File.Exists(file)?Engine.Json.Deserialize<List<TavernListeningGroup>>(File.ReadAllText(file)).Where(g=>g.level==level).ToList():new List<TavernListeningGroup>();}
 void ShowTavernListeningList(int level){var t=TavernBusiness.State(save);if(!t.settled&&t.mode!=null&&t.mode!="listening"){ShowTavernBusiness();return;}var body=BusinessPage("吧台 · 咒语学习 · "+(level==4?"四级":"六级"),false);BusinessText(body,"只做单组练习，材料可以无限重听。提交后查看答案和解析，再选择下一组。每道题每天只奖励一次，两种训练共享50金币上限。");foreach(var group in TavernListeningBank(level)){var selected=group;body.Controls.Add(PartyButton(group.title+" · "+group.questions.Count+"题",()=>{if(!t.settled&&!TavernBusiness.Begin(save,"listening")){ShowTavernBusiness();return;}Persist();ShowTavernListeningGroup(selected);},450,44));}BusinessText(body,"当前题库为原创模拟，非历年真题。真题材料上传后另行接入。");body.Controls.Add(PartyButton("返回经营",ShowTavernBusiness,420,40));}
 void ShowTavernListeningGroup(TavernListeningGroup group){var body=BusinessPage("咒语学习 · "+group.title,false);BusinessText(body,group.source+"\n先阅读选项，再听材料和音频中的问题；不限重听次数。");string audio=Path.Combine(root,"assets","tavern","listening",group.audio);Action play=()=>{mciSendString("close tavernlisten",null,0,IntPtr.Zero);string path=AudioDevicePath.Relative(AudioVolume.Prepare(audio,StorySoundVolume(),root));int error=mciSendString("open \""+path+"\" type waveaudio alias tavernlisten",null,0,IntPtr.Zero);if(error==0)error=mciSendString("play tavernlisten",null,0,IntPtr.Zero);if(error!=0)GameMessage.Show(this,"听力音频无法播放，请检查材料文件。");};body.Controls.Add(PartyButton("播放 / 重听本段",play,420,42));body.Controls.Add(PartyButton("暂停音频",()=>mciSendString("pause tavernlisten",null,0,IntPtr.Zero),420,38));body.Controls.Add(PartyButton("继续播放",()=>mciSendString("resume tavernlisten",null,0,IntPtr.Zero),420,38));var choices=new RadioButton[group.questions.Count][];for(int i=0;i<group.questions.Count;i++){BusinessText(body,"Question "+(i+1));var row=new FlowLayoutPanel{Width=body.Parent.Width-70,Height=130,FlowDirection=FlowDirection.TopDown,WrapContents=false,BackColor=Color.Transparent};body.Controls.Add(row);choices[i]=new RadioButton[4];for(int j=0;j<4;j++){var option=new RadioButton{Text=((char)('A'+j))+". "+group.questions[i].options[j],Width=row.Width-10,Height=30,ForeColor=TextColor,Font=GameTheme.Body(11)};row.Controls.Add(option);choices[i][j]=option;}}bool submitted=false;body.Controls.Add(PartyButton("提交本组答案",()=>{if(submitted)return;if(choices.Any(c=>!c.Any(x=>x.Checked))){GameMessage.Show(this,"请完成本组所有题目后提交。");return;}submitted=true;mciSendString("stop tavernlisten",null,0,IntPtr.Zero);int count=0,gain=0;for(int i=0;i<choices.Length;i++){bool ok=choices[i][group.questions[i].answer].Checked;if(ok)count++;gain+=TavernBusiness.Reward(save,"listen:"+group.id+":"+i,ok);foreach(var choice in choices[i])choice.Enabled=false;BusinessText(body,"第"+(i+1)+"题 · "+(ok?"正确":"错误")+" · 答案"+(char)('A'+group.questions[i].answer)+"\n"+group.questions[i].explanation);}TavernBusiness.State(save).groups++;Persist();BusinessText(body,"答对 "+count+" / "+choices.Length+" · 获得"+gain+"金币\n材料原文："+group.transcript);body.Controls.Add(PartyButton("再做一组 / 重做本组",()=>ShowTavernListeningList(group.level),420,44));},420,44));body.Controls.Add(PartyButton("返回题组列表",()=>ShowTavernListeningList(group.level),420,40));}
}
